//! Throwaway P3 probe (2026-11-23-canvas-placement-and-text): what size a widget's paint gets and
//! where its scene lands under padding, a border and a transform (upstream #1578), and whether a
//! widget can draw text from the stand's bundled DejaVu Sans through its own font context.

use std::sync::{Arc, Mutex};

use anyrender::{AntiAliasing, PaintScene as _};
use blitz_dom::Widget;
use blitz_dom::node::ComputedStyles;
use dioxus::prelude::*;
use dioxus_native_dom::CustomWidgetAttr;
use peniko::kurbo::{Affine, Rect};
use peniko::{Color, Fill};
use seven_guis::stand;

type Got = Arc<Mutex<Option<(u32, u32, f64)>>>;

struct RedFill(Got);

impl Widget for RedFill {
    fn paint(
        &mut self,
        _ctx: &mut dyn anyrender::RenderContext,
        _styles: &ComputedStyles,
        width: u32,
        height: u32,
        scale: f64,
    ) -> anyrender::Scene {
        *self.0.lock().unwrap() = Some((width, height, scale));
        let mut scene = anyrender::Scene::new();
        scene.fill(
            Fill::NonZero,
            Affine::IDENTITY,
            Color::from_rgb8(255, 0, 0),
            None,
            &Rect::new(0.0, 0.0, f64::from(width), f64::from(height)),
            AntiAliasing::default(),
        );
        scene
    }
}

static STYLE: Mutex<&'static str> = Mutex::new("");
static GOT: Mutex<Option<Got>> = Mutex::new(None);

#[component]
fn Boxed() -> Element {
    let got = GOT.lock().unwrap().clone().unwrap();
    let attr = use_hook(|| CustomWidgetAttr::new(RedFill(got)));
    let style = *STYLE.lock().unwrap();
    rsx! { object { id: "probe", style: "{style}", "data": attr } }
}

fn px(r: &blitz_test_harness::Raster, x: u32, y: u32) -> [u8; 4] {
    let at = ((y * r.width + x) * 4) as usize;
    [r.rgba[at], r.rgba[at + 1], r.rgba[at + 2], r.rgba[at + 3]]
}

fn run(style: &'static str, points: &[(u32, u32)]) {
    for incremental in [false, true] {
        let got: Got = Arc::new(Mutex::new(None));
        *STYLE.lock().unwrap() = style;
        *GOT.lock().unwrap() = Some(got.clone());
        let mut h = stand::boot_alone(Boxed, || (), stand::options(incremental));
        let r = h.screenshot().expect("paints");
        let read: Vec<_> = points
            .iter()
            .map(|&(x, y)| ((x, y), px(&r, x, y)))
            .collect();
        println!(
            "PROBE incremental={incremental} style={style:?} paint_size={:?} pixels={read:?}",
            got.lock().unwrap()
        );
    }
}

#[test]
fn placement_with_padding_and_border() {
    // body margin 8: border box (8,8)-(138,98), content box (23,23)-(123,83).
    run(
        "display: block; box-sizing: content-box; width: 100px; height: 60px; padding: 12px; border: 3px solid black;",
        &[
            (50, 50),
            (120, 80),
            (125, 50),
            (130, 50),
            (145, 50),
            (50, 90),
            (50, 105),
        ],
    );
}

#[test]
fn placement_under_a_scale_transform() {
    // transform-origin 0 0, scale(2): content origin (15,15) local -> M*T gives device 8+30 = 38;
    // T*M (today) gives 8+15 = 23.
    run(
        "display: block; box-sizing: content-box; width: 100px; height: 60px; padding: 12px; border: 3px solid black; transform-origin: 0 0; transform: scale(2);",
        &[
            (26, 26),
            (34, 34),
            (40, 40),
            (236, 100),
            (245, 100),
            (255, 100),
        ],
    );
}

#[test]
fn placement_with_no_padding_or_border() {
    run(
        "display: block; width: 200px; height: 100px;",
        &[(58, 58), (207, 107), (209, 109)],
    );
}

// ---- canvas text through the widget's own font context (route B) ----

struct TextWidget {
    fcx: parley::FontContext,
    lcx: parley::LayoutContext<()>,
}

impl Widget for TextWidget {
    fn paint(
        &mut self,
        _ctx: &mut dyn anyrender::RenderContext,
        _styles: &ComputedStyles,
        _width: u32,
        _height: u32,
        _scale: f64,
    ) -> anyrender::Scene {
        let mut scene = anyrender::Scene::new();
        let text = "Hg";
        let mut builder = self.lcx.ranged_builder(&mut self.fcx, text, 1.0, true);
        builder.push_default(parley::StyleProperty::FontSize(40.0));
        builder.push_default(parley::GenericFamily::SansSerif);
        let mut layout = builder.build(text);
        layout.break_all_lines(None);
        for line in layout.lines() {
            for item in line.items() {
                if let parley::PositionedLayoutItem::GlyphRun(gr) = item {
                    let run = gr.run();
                    scene.draw_glyphs(
                        run.font(),
                        run.font_size(),
                        true,
                        &[],
                        peniko::kurbo::Vec2::default(),
                        Fill::NonZero,
                        &anyrender::Paint::from(Color::from_rgb8(0, 0, 0)),
                        1.0,
                        Affine::IDENTITY,
                        None,
                        gr.positioned_glyphs().map(|g| anyrender::Glyph {
                            id: g.id as _,
                            x: g.x,
                            y: g.y,
                        }),
                        AntiAliasing::Enabled,
                    );
                }
            }
        }
        scene
    }
}

#[component]
fn TextCanvas() -> Element {
    let attr = use_hook(|| {
        CustomWidgetAttr::new(TextWidget {
            fcx: blitz_dom::build_single_font_ctx(seven_guis::DEJAVU_SANS),
            lcx: parley::LayoutContext::new(),
        })
    });
    rsx! { object { id: "text", style: "display: block; width: 200px; height: 100px;", "data": attr } }
}

#[test]
fn canvas_text_from_its_own_bundled_font_context() {
    let mut shots = Vec::new();
    for incremental in [false, true] {
        let mut h = stand::boot_alone(TextCanvas, || (), stand::options(incremental));
        let r = h.screenshot().expect("paints");
        let mut dark = 0;
        for y in 8..108 {
            for x in 8..208 {
                if px(&r, x, y)[0] < 128 {
                    dark += 1;
                }
            }
        }
        println!("PROBE text incremental={incremental} dark_pixels_in_canvas={dark}");
        shots.push(r.rgba.clone());
    }
    println!("PROBE text both_modes_byte_equal={}", shots[0] == shots[1]);
}

// ---- route A: the document's own font context handed to the widget ----

struct DocFontText {
    fonts: Option<Arc<Mutex<parley::FontContext>>>,
    lcx: parley::LayoutContext<()>,
}

impl Widget for DocFontText {
    fn fonts(&mut self, fonts: &Arc<Mutex<parley::FontContext>>) {
        self.fonts = Some(Arc::clone(fonts));
    }
    fn paint(
        &mut self,
        _ctx: &mut dyn anyrender::RenderContext,
        _styles: &ComputedStyles,
        _width: u32,
        _height: u32,
        _scale: f64,
    ) -> anyrender::Scene {
        let mut scene = anyrender::Scene::new();
        let Some(fonts) = self.fonts.clone() else {
            return scene;
        };
        let mut fcx = fonts.lock().unwrap();
        let text = "Hg";
        let mut builder = self.lcx.ranged_builder(&mut fcx, text, 1.0, true);
        builder.push_default(parley::StyleProperty::FontSize(40.0));
        builder.push_default(parley::GenericFamily::SansSerif);
        let mut layout = builder.build(text);
        layout.break_all_lines(None);
        for line in layout.lines() {
            for item in line.items() {
                if let parley::PositionedLayoutItem::GlyphRun(gr) = item {
                    let run = gr.run();
                    scene.draw_glyphs(
                        run.font(),
                        run.font_size(),
                        true,
                        &[],
                        peniko::kurbo::Vec2::default(),
                        Fill::NonZero,
                        &anyrender::Paint::from(Color::from_rgb8(0, 0, 0)),
                        1.0,
                        Affine::IDENTITY,
                        None,
                        gr.positioned_glyphs().map(|g| anyrender::Glyph {
                            id: g.id as _,
                            x: g.x,
                            y: g.y,
                        }),
                        AntiAliasing::Enabled,
                    );
                }
            }
        }
        scene
    }
}

#[component]
fn DocFontCanvas() -> Element {
    let attr = use_hook(|| {
        CustomWidgetAttr::new(DocFontText {
            fonts: None,
            lcx: parley::LayoutContext::new(),
        })
    });
    rsx! { object { id: "text", style: "display: block; width: 200px; height: 100px;", "data": attr } }
}

#[test]
fn canvas_text_from_the_documents_own_font_context() {
    let mut shots = Vec::new();
    for incremental in [false, true] {
        let mut h = stand::boot_alone(DocFontCanvas, || (), stand::options(incremental));
        let r = h.screenshot().expect("paints");
        let mut dark = 0;
        for y in 8..108 {
            for x in 8..208 {
                if px(&r, x, y)[0] < 128 {
                    dark += 1;
                }
            }
        }
        println!("PROBE doctext incremental={incremental} dark_pixels_in_canvas={dark}");
        shots.push(r.rgba.clone());
    }
    let mut h = stand::boot_alone(TextCanvas, || (), stand::options(false));
    let own = h.screenshot().expect("paints").rgba;
    println!(
        "PROBE doctext both_modes_byte_equal={} equal_to_route_b={}",
        shots[0] == shots[1],
        shots[0] == own
    );
}
